#toggle() {
  if (this.#minimized) {
    document.getElementById("tabmail").globalOverlay = true;
    this.#modal.showModal();
  } else {
    this.#modal.close();
  }
  this.#placeholder.hidden = this.#minimized;
  this.#modal.classList.toggle("minimized", !this.#minimized);
  this.#minimized = !this.#minimized;
